import os, pty, sys, time, select, signal

def run(args, send2=b"q"):
    pid, fd = pty.fork()
    if pid == 0:
        env = {"PATH":"/tmp/recon-io/bin:/usr/bin:/bin","HOME":"/tmp/fakehome","TERM":"xterm"}
        os.execvpe("/workspace/executable", ["executable"]+args, env)
    out=b""
    end=time.time()+1.2
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.1)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d
    if send2: os.write(fd, send2)
    end=time.time()+0.8
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.1)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d
    wpid,status=os.waitpid(pid,os.WNOHANG)
    alive=(wpid==0)
    if alive:
        os.kill(pid,signal.SIGTERM); time.sleep(0.2)
        try: os.waitpid(pid,0)
        except ChildProcessError: pass
    print(f"ARGS={args} exit={'ALIVE' if alive else os.waitstatus_to_exitcode(status)}")
    print(repr(out[:300])); print("---")

run(["--paging=always","a.txt"])
run(["--paging=never","a.txt"])
EOF
